(() => {
  // javascript/script.js
  function toggleMenu() {
    const menuId = this.getAttribute("aria-controls");
    const menu = document.getElementById(menuId);
    let menuState = menu.getAttribute("armch-menu-state");
    if (menuState === "collapsed") {
      menu.setAttribute("armch-menu-state", "expanded");
    } else {
      menu.setAttribute("armch-menu-state", "collapsed");
    }
  }
  var primaryMenuToggler = document.querySelector(
    '.menu-toggler[aria-controls="primary-menu"]'
  );
  primaryMenuToggler.addEventListener("click", toggleMenu);
  function colophonMenuIcons() {
    const menuItems = document.querySelectorAll(
      ".widget_nav_menu .menu > .menu-item"
    );
    menuItems.forEach((elem) => {
      let icon = document.createElement("i");
      icon.classList.add("fa-solid", "fa-caret-right");
      elem.prepend(icon);
    });
  }
  document.addEventListener("DOMContentLoaded", colophonMenuIcons);
  if (typeof jQuery !== "undefined") {
    jQuery(document).ready(function() {
      const load_posts = function($) {
        let page = 1;
        let loading = false;
        const expedicionesContainer = $("#expediciones-container");
        const loader = $("#loader");
        function loadExpediciones() {
          if (loading) return;
          loading = true;
          loader.show();
          $.ajax({
            url: armchExpediciones.ajaxUrl,
            type: "POST",
            data: {
              action: "load_expediciones",
              paged: page,
              nonce: armchExpediciones.nonce
            },
            success: function(response) {
              if (response.success) {
                console.log(response.data);
                expedicionesContainer.append(response.data.content);
                page++;
                loading = false;
                loader.hide();
              } else {
                loader.html(
                  '<p>Eso fue todo por ahora. Quer\xE9s m\xE1s informaci\xF3n? Contactanos por WhatsApp al <a href="https://web.whatsapp.com/send?phone=5493884155055" target="_blank">5493884155055</a>!</p>'
                );
              }
            },
            error: function() {
              loader.text("Error al cargar expediciones.");
            }
          });
        }
        function init() {
          loadExpediciones();
          $(window).on("scroll", function() {
            if ($(window).scrollTop() + $(window).height() >= $(document).height() - 100) {
              loadExpediciones();
            }
          });
        }
        return {
          init
        };
      }(jQuery);
      load_posts.init();
    });
  } else {
    console.error(
      "jQuery no est\xE1 definido. Aseg\xFArate de que jQuery se cargue antes de este script."
    );
  }
})();
